def main():
    print(f"Loaded {len(SCRIPTS)} scripts.")
    
    # Verify strict no ellipses rule
    for s in SCRIPTS:
        for t_idx, turn in enumerate(s["turns"]):
            spk, lines, photo = turn
            for pair in lines:
                for txt in pair:
                    if "..." in txt or "…" in txt:
                        raise ValueError(f"Script {s['num']} turn {t_idx} has ellipses: '{txt}'")

    print("✅ Strict No-Ellipses Rule Verified 100% across all 20 scripts!")

    # 1. Write scripts.json
    json_path = DOCS_DIR / "hatari_cyclone_max_20_scripts.json"
    with open(json_path, "w", encoding="utf-8") as f:
        json.dump(SCRIPTS, f, ensure_ascii=False, indent=2)
    print(f"✅ Saved {json_path}")

    # 2. Write scripts.md readable catalog
    md_path = DOCS_DIR / "hatari_cyclone_max_20_scripts.md"
    lines = [
        "# 🌪️ Master Scripts: Hatari Cyclone Max พัดลมตั้งโต๊ะ 8 นิ้ว (PS8M1) 20 บทสไตล์คู่รักสายใต้ (#5 Couple Paper Chat)\n",
        "> บทสนทนาคู่รักสายใต้ (น้องนุ้ย & พี่บ่าว) ดราม่าโบ๊ะบ๊ะบ่นด่ากวนๆ 40-50 วินาที ไร้จุดไข่ปลา พร้อมช็อต CTA แบบ Brand & Model First\n",
        "| ลำดับ | รหัส | หมวดหมู่ | ชื่อตอน | ฮุก | จำนวนเทิร์น | รูปภาพ |",
        "|:---:|:---|:---|:---|:---|:---:|:---:|"
    ]
    for s in SCRIPTS:
        cid = f"hat02-pov-s{s['num']:02d}"
        n_turns = len(s["turns"])
        n_photos = sum(1 for t in s["turns"] if t[2] is not None)
        lines.append(f"| {s['num']} | `{cid}` | {s['category'][:22]} | {s['title']} | {s['hook_title'][:35]}... | {n_turns} เทิร์น | {n_photos} รูป |")

    lines.append("\n---\n")
    for s in SCRIPTS:
        cid = f"hat02-pov-s{s['num']:02d}"
        lines.append(f"## {s['num']}. `{cid}` — {s['title']}")
        lines.append(f"- **หมวดหมู่**: {s['category']}")
        lines.append(f"- **Hook**: {s['hook_title']}")
        lines.append(f"- **Scenario**: {s['scenario']}")
        lines.append(f"- **CTA Phrase**: `{s['cta_phrase']}`\n")
        lines.append("### บทพูดและช็อตภาพ:")
        for t_idx, turn in enumerate(s["turns"], 1):
            spk, t_lines, photo = turn
            name = "น้องนุ้ย (F)" if spk == "F" else "พี่บ่าว (M)"
            bubble_txt = " / ".join(p[0] for p in t_lines)
            spoken_txt = " ".join(p[1] for p in t_lines)
            photo_info = f" 📸 `[{photo[1]}]`" if photo else ""
            lines.append(f"{t_idx}. **{name}**: {bubble_txt}{photo_info}")
            lines.append(f"   - *เสียงพากย์:* \"{spoken_txt}\"")
        lines.append("\n---\n")

    md_path.write_text("\n".join(lines), encoding="utf-8")
    print(f"✅ Saved {md_path}")

    # 3. Sync into _Docs/products.json under cde38b1c07e54ea69a3d50a6c1bb3f18
    products_file = DOCS_DIR / "products.json"
    products = json.loads(products_file.read_text(encoding="utf-8"))
    p = next((prod for prod in products if prod.get("id") == "cde38b1c07e54ea69a3d50a6c1bb3f18"), None)
    if p:
        p["product_code"] = "HAT02"
        new_angles = []
        for s in SCRIPTS:
            num = s["num"]
            cid = f"hat02-pov-s{num:02d}"
            angle = {
                "angle_id": f"ang_hat02_{num:02d}",
                "internal_id": f"angle_{num}",
                "clip_id": cid,
                "angle_name": s["title"],
                "badge": "ขายดีอันดับ 1" if num == 1 else ("แนะนำ" if num in [5, 9, 13, 17] else "ฮิตใน TikTok"),
                "product_name": "Hatari Cyclone Max 8 นิ้ว (PS8M1)",
                "hook_title": s["hook_title"],
                "pain_point": s["scenario"],
                "key_features": "พลังลมไซโคลน 3 ระดับ, ก้มเงย 90 องศา, มอเตอร์ Ball Bearing เงียบทน, ตัดไฟอัตโนมัติ Thermal Fuse, ตะแกรงถอดล้างง่าย, แขวนผนังได้",
                "price_deal": "โปรโมชั่นราคาพิเศษในตะกร้าสีเหลือง",
                "ad_tone": "couple_paper_chat",
                "script_lines": [p[1] for turn in s["turns"] for p in turn[1]],
                "script_text": "\n".join(" ".join(p[1] for p in turn[1]) for turn in s["turns"]),
                "tts_lines": [p[1] for turn in s["turns"] for p in turn[1]],
                "status": "scripted",
                "duration": "48s"
            }
            new_angles.append(angle)
        p["angles"] = new_angles
        products_file.write_text(json.dumps(products, ensure_ascii=False, indent=2), encoding="utf-8")
        print(f"✅ Synced 20 angles into _Docs/products.json for Hatari Cyclone Max (HAT02)")

if __name__ == "__main__":
    main()
